import{_ as l,c as e,o as i,ah as c}from"./chunks/framework.BkHe6ehV.js";const p=JSON.parse('{"title":"腾讯系列","description":"","frontmatter":{"title":"腾讯系列","date":"2025-12-31 10:45:37","create":"2025-12-31 10:45:37","categories":[],"tags":[],"readingStats":{"words":5196,"minutes":16,"images":0}},"headers":[],"relativePath":"posts/llm/industry/mainllm/11-tencent-series.md","filePath":"posts/llm/industry/mainllm/11-tencent-series.md","lastUpdated":1785944275000}'),t={name:"posts/llm/industry/mainllm/11-tencent-series.md"};function d(s,o,n,a,r,u){return i(),e("div",null,o[0]||(o[0]=[c('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.08 · <a href="#_2608-hy4-preview-gated-dsa、indexcache、1m">Hy4 preview</a></strong></p><ul><li>采用 <code>Gated DSA + IndexCache</code>，复用历史选择结果，支持 <code>1M</code> 上下文。</li><li>扩大预训练与后训练，加入多个行业的专家数据。</li></ul><p><strong>2026.07 · <a href="#_2607-hy3-产品反馈、多轮-sft-rl">Hy3</a></strong></p><ul><li>将产品反馈纳入多轮 SFT 与 RL，强化真实任务交付。</li><li>重点改善复杂约束遵循、多轮操作与失败恢复。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.06 · <a href="#_2506-hunyuan-a13b-80b-a13b、四阶段后训练、双模式思考">Hunyuan-A13B</a></strong></p><ul><li>以 <code>80B 总参数 / 13B 激活</code> 降低计算开销，支持快慢两种思考模式。</li><li>通过分阶段 SFT 与 RL 融合推理和通用能力。</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前</div><p><strong>2024.11 · <a href="#_2411-hunyuan-large-389b-a52b、cla、recycle-routing">Hunyuan-Large</a></strong></p><ul><li>采用大规模 MoE，CLA 共享 KV，Recycle Routing 提高专家利用率。</li><li>结合预训练与偏好对齐，建立混元大模型基座。</li></ul></div><h2 id="_2608-hy4-preview-gated-dsa、indexcache、1m" tabindex="-1">(2608) Hy4 preview (Gated DSA、IndexCache、1M) <a class="header-anchor" href="#_2608-hy4-preview-gated-dsa、indexcache、1m" aria-label="Permalink to &quot;(2608) Hy4 preview (Gated DSA、IndexCache、1M)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Hy4 preview</div><p><strong>参考链接</strong></p><ul><li><a href="https://huggingface.co/tencent/Hy4-preview" target="_blank" rel="noreferrer">官方模型卡</a>、<a href="https://www.tencent.com/tencent-releases-and-open-sources-tencent-hy4-preview/" target="_blank" rel="noreferrer">发布说明</a>。</li></ul><p><strong>架构优化</strong></p><ul><li>主干 <code>770B-A49B</code>、<code>1M</code> 上下文；每 token 选择 <code>8</code> 个路由专家并使用共享专家。</li><li>Gated DSA 选择 <code>Top-2048</code> 历史位置；IndexCache 跨层复用位置索引，减少重复筛选。</li><li>iHC 使用 <code>4</code> 条残差流；额外 <code>1</code> 层 MTP 生成 Draft Token，由主模型批量验证。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">专家数据与产品迭代</div><ul><li>扩展预训练与后训练，软件、游戏、金融、安全专家共同构建真实工作数据。</li><li>训练面向跨文件调试、多资料文档、可玩原型和科研分析，强调可使用的最终产物。</li><li>与 CodeBuddy、WorkBuddy 联合迭代；开放 BF16/FP8 权重与原生 MTP。</li></ul></div><div class="custom-block important"><div class="custom-block-title">内部工程盲测</div><ul><li><code>163</code> 名专家评审 <code>203</code> 项任务，采用匿名并排比较与四分制评分。</li><li>Hy4 均分 <code>2.99</code>，Kimi K3 <code>2.94</code>、GLM-5.3 <code>2.92</code>，该任务集上小幅领先。</li><li>对 Kimi K3：<code>51.2%胜 / 7.9%平 / 40.9%负</code>；仍有较多任务不占优。</li><li>官方仍观察到思考过久和重复自检，复杂任务需要同时优化完成质量与耗时。</li></ul></div><h2 id="_2607-hy3-产品反馈、多轮-sft-rl" tabindex="-1">(2607) Hy3 (产品反馈、多轮 SFT + RL) <a class="header-anchor" href="#_2607-hy3-产品反馈、多轮-sft-rl" aria-label="Permalink to &quot;(2607) Hy3 (产品反馈、多轮 SFT + RL)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Hy3</div><p><strong>参考链接</strong></p><ul><li><a href="https://huggingface.co/tencent/Hy3" target="_blank" rel="noreferrer">官方模型卡</a>、<a href="https://www.tencent.com/tencent-hunyuan-officially-releases-hy3-advancing-agent-capabilities-and-deeper-product-integration/" target="_blank" rel="noreferrer">官方发布</a>。</li></ul><p><strong>模型与训练</strong></p><ul><li><code>295B-A21B</code> MoE、<code>256K</code> 上下文；GQA + MTP，提供 <code>no_think / low / high</code>。</li><li>利用 <code>50+</code> 产品反馈扩展 SFT 与 RL 数据，针对工具错误、知识混淆和多轮约束丢失。</li></ul><p><strong>后训练重点</strong></p><ul><li>工具：稳定调用和参数，训练报错后的恢复，适配不同 harness。</li><li>知识：清洗来源混淆、虚构数据与常识错误，训练基于证据的回答。</li><li>多轮：恢复省略和指代信息，保持长期意图、早期约束及后续需求修改。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">任务表现与错误变化</div><ul><li>内部 <code>270</code> 名专家工作盲测：Hy3 <code>2.67/4</code>，GLM-5.1 <code>2.51/4</code>。</li><li>内部幻觉率 <code>12.5% → 5.4%</code>，常识错误率 <code>25.4% → 12.7%</code>。</li><li>多轮问题率 <code>17.4% → 7.9%</code>，体现跨轮约束保持和意图跟踪的改善。</li><li>SWE-V 在 CodeBuddy、Cline、KiloCode 等 harness 下的波动控制在官方报告的 <code>4%</code> 以内。</li></ul></div><h2 id="_2506-hunyuan-a13b-80b-a13b、四阶段后训练、双模式思考" tabindex="-1">(2506) Hunyuan-A13B (80B-A13B、四阶段后训练、双模式思考) <a class="header-anchor" href="#_2506-hunyuan-a13b-80b-a13b、四阶段后训练、双模式思考" aria-label="Permalink to &quot;(2506) Hunyuan-A13B (80B-A13B、四阶段后训练、双模式思考)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Hunyuan-A13B 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://github.com/Tencent-Hunyuan/Hunyuan-A13B/blob/main/report/Hunyuan_A13B_Technical_Report.pdf" target="_blank" rel="noreferrer">paper</a>，<a href="https://github.com/Tencent-Hunyuan/Hunyuan-A13B" target="_blank" rel="noreferrer">模型与代码</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>大模型推理成本较高；希望以更低激活量保留推理、代码与 Agent 能力，并按任务控制思考开销。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>架构与预训练</strong>：<code>80B-A13B</code> MoE + GQA；<code>20T</code> 基础训练、<code>300B</code> 退火，再扩展到 <code>256K</code>。</li><li><strong>推理 SFT → GRPO</strong>：使用 <code>150K</code> 数学/代码/逻辑/科学任务，Verifier 与 Sandbox 提供奖励。</li><li><strong>通用 SFT → RL</strong>：五角色合成 Agent 轨迹，覆盖多工具反馈与 <code>20K</code> 格式；Dual-CoT 统一快慢思考。</li></ul><p><strong>模型效果(A13B-Instruct，快思考 → 慢思考)</strong></p><ul><li>AIME 2024：<code>30.6</code> → <code>87.3</code>；BFCL v3：<code>65.9</code> → <code>78.3</code>。</li><li>LongBench-v2 <code>55.0</code>，高于报告中的 Qwen3-A22B <code>48.4</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>慢思考对数学、逻辑和部分工具任务收益明显；快慢模式的优劣仍取决于具体任务。</li><li>Base 相比 Hunyuan-Large，在 <code>12/14</code> 项评测上改善，激活参数由 <code>52B</code> 降至 <code>13B</code>。</li></ul><p><strong>核心贡献</strong></p><ul><li>给出低激活 MoE、推理与通用分阶段后训练、双思考模式的完整训练方案，并开放 Base/Instruct 权重。</li></ul><p><strong>未来方向</strong></p><ul><li>补强复杂代码与多跳 RAG；进一步按任务收益分配快慢思考预算。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">推理能力与使用成本</div><p><strong>激活规模与成本</strong></p><ul><li>大模型完整激活会增加推理延迟和硬件开销；MoE 用部分专家计算，降低每 token 的成本。</li></ul><p><strong>推理深度与任务需求</strong></p><ul><li>数学、代码需要较长推理；日常问答若总生成长 CoT，会增加无必要的等待。</li><li>后训练同时需要保留通用交互能力，避免模型只适合可验证推理题。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="架构与预训练" tabindex="-1">架构与预训练 <a class="header-anchor" href="#架构与预训练" aria-label="Permalink to &quot;架构与预训练&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">模型结构</div><p><strong>MoE</strong></p><ul><li><code>32层</code>，<code>80B</code> 总参数，<code>13B</code> 激活；共享专家与路由专家的中间维度相同。</li><li><code>1个共享专家</code>始终激活，从 <code>64个路由专家</code>中选择 <code>Top-8</code>。</li><li>共享专家负责可复用计算；报告的结构探索发现，增加至一个共享专家收益明显，继续增加收益减弱。</li></ul><p><strong>Attention 与词表</strong></p><ul><li>GQA：<code>32个 Query Head / 8个 KV Head</code>，减少 KV Cache。</li><li><code>hidden=4096, FFN=3072</code>，SwiGLU；沿用 Hunyuan-Large 的 <code>128K</code> 词表。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">预训练语料</div><p><strong>清洗流程</strong></p><ul><li>预处理去重、去噪、低质量过滤和主题标注，再由模型抽取正文。</li><li>对抽取文本继续做质量过滤与语义去重，减少重复、格式残留和无效内容。</li></ul><p><strong>STEM 与难度分级</strong></p><ul><li>优化 STEM 获取与清洗，提取 <code>250B tokens</code> 高质量 STEM 语料。</li><li>细化知识标签，并从多个维度标注难度，使语料筛选能覆盖不同知识和推理需求。</li></ul></div><div class="custom-block info"><div class="custom-block-title">预训练课程</div><p><strong>基础训练与快速退火</strong></p><ul><li>基础阶段 <code>20T tokens</code>，固定 <code>4K</code> 长度；学习率先预热、再余弦下降，最后保持最低值。</li><li>快速退火追加 <code>300B tokens</code>，上下文扩到 <code>8K</code>，用更低学习率巩固能力。</li></ul><p><strong>长上下文扩展</strong></p><ul><li>分两阶段训练至 <code>32K</code>、<code>256K</code>，使用 NTK-aware 位置编码。</li><li>增加可处理长度后，用真实长文理解与多跳任务检查模型是否能有效利用远处信息。</li></ul></div><h4 id="推理-sft-与-rl" tabindex="-1">推理 SFT 与 RL <a class="header-anchor" href="#推理-sft-与-rl" aria-label="Permalink to &quot;推理 SFT 与 RL&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">推理数据构建</div><p><strong>数学与代码</strong></p><ul><li><strong>数学</strong>：教材、标准化考试、竞赛题；结合生成式奖励模型与自动验证筛选长 CoT。</li><li><strong>代码</strong>：从开源仓库抽取代码，合成指令和推理过程，由 Critic 与 Sandbox 检查正确性。</li></ul><p><strong>逻辑与科学</strong></p><ul><li><strong>逻辑</strong>：按题型和难度合成谜题，常规题用模型验证，复杂题加入人工复核。</li><li><strong>科学</strong>：覆盖物理、化学、生物，Verifier 检查单位换算、数值近似和化学符号等细节。</li><li>四类数据都保留明确推理过程，拒绝验证失败的样本。</li></ul></div><div class="custom-block important"><div class="custom-block-title">推理 RL</div><p><strong>奖励来源</strong></p><ul><li><strong>Outcome Verifier</strong>：比较最终答案与参考答案，输出 <code>0/1</code>，兼容等价格式、单位和同义表达。</li><li><strong>Code Sandbox</strong>：执行代码与测试，覆盖 <code>36种语言</code>，通过分布式 CPU 集群并发运行。</li></ul><p><strong>可学习样本</strong></p><ul><li>从 SFT 模型表现不稳定的题目中选取 RL 数据，保留当前模型有提升空间的任务。</li><li>排除选择、判断和证明题，减少猜中答案或难以判定正确性的奖励噪声。</li><li>采用 GRPO，逐阶段延长上下文；去掉 KL 约束，结合近 On-Policy、大 Batch 和较多 Rollout。</li></ul></div><h4 id="通用能力与快慢思考" tabindex="-1">通用能力与快慢思考 <a class="header-anchor" href="#通用能力与快慢思考" aria-label="Permalink to &quot;通用能力与快慢思考&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">通用能力数据</div><p><strong>任务混合</strong></p><ul><li>混合部分推理数据，以及写作、理解、翻译、多轮对话、知识问答、复杂指令和角色扮演。</li><li>复杂指令数据包含多约束与跨文本信息整合，并用规则检查约束是否满足。</li><li>知识问答由 Critic 过滤无依据内容；多轮数据混合开源、采购、合成与模拟对话。</li></ul><p><strong>Agent 合成</strong></p><ul><li>使用 <code>User、Planner、Tool、Agent、Checker</code> 五角色引擎生成多方交互。</li><li>工具反馈来自 Sandbox、MCP 与合成工具，扩展工具种类和环境反馈。</li><li>设计 <code>30余类</code> System Instruction，组合工具、动作和回答格式，形成 <code>20K</code> 格式组合。</li><li>补充快慢思考数据，并强化 Excel、Deep Search 等高频工作任务。</li></ul></div><div class="custom-block note"><div class="custom-block-title">领域奖励服务</div><p><strong>GRM</strong></p><ul><li>以参考回答为判断依据，比较候选质量；开放任务用语义参考，确定性任务用标准答案。</li><li>可结合 CoT、外部工具、长度统计与约束检查，适应不同领域。</li><li>覆盖 <code>16个子主题</code>、<code>30余个评分服务</code>，通过动态采样平衡任务。</li></ul><p><strong>Agent 与长对话</strong></p><ul><li><strong>格式奖励</strong>：工具特殊标记及顺序正确记 <code>1</code>，否则 <code>0</code>，保证调用可解析。</li><li><strong>正确性奖励</strong>：比较工具、参数及参数值与参考调用的一致性。</li><li>长上下文增加幻觉检测奖励；多轮对话挖掘不稳定样本，改进上下文连贯性。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">双模式统一训练</div><p><strong>统一格式</strong></p><ul><li>快慢样本共用输出格式；快思考保留空 Thinking 内容，慢思考包含逐步推理。</li><li>两种模式在同一后训练结构中优化，使用一个模型提供不同推理深度。</li></ul><p><strong>推理选择</strong></p><ul><li>快思考处理直接问答，减少生成开销；慢思考支持反思、回溯和复杂推理。</li><li>通过 <code>/no_think</code> 与 <code>/think</code> 控制；未指定时默认慢思考。</li></ul></div><h3 id="实验设置-a13b-四阶段后训练" tabindex="-1">实验设置(A13B，四阶段后训练) <a class="header-anchor" href="#实验设置-a13b-四阶段后训练" aria-label="Permalink to &quot;实验设置(A13B，四阶段后训练)&quot;">​</a></h3><p><strong>✍️ 实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">训练配置</div><p><strong>基础模型与预训练</strong></p><ul><li><strong>Hunyuan-A13B</strong>：<code>80B-A13B</code>，<code>32层</code>，共享专家 <code>1</code>、路由专家 <code>64/Top-8</code>。</li><li>基础训练：<code>20T tokens, seq_len=4K, peak_lr=3e-4</code>。</li><li>学习率在 <code>13.5T tokens</code> 内余弦降到 <code>3e-5</code>，剩余基础训练保持该值。</li><li>快速退火：<code>300B tokens, seq_len=8K, lr=3e-5→8e-6</code>。</li><li>长上下文：<code>32K → 256K</code>，NTK-aware 的 <code>alpha=50 → 1000</code>。</li></ul><p><strong>推理 RL 数据与超参</strong></p><ul><li><code>150K</code> 任务；数学:代码:逻辑:科学=<code>2:2:1:1</code>。</li><li>与 SFT 重合 <code>10%</code>，新增任务 <code>90%</code>；训练长度 <code>24K → 32K</code>。</li><li>GRPO：移除 KL 约束，采样温度 <code>0.6～0.8</code>。</li><li>四阶段顺序：推理 SFT → 推理 RL → 通用 SFT → 通用 RL。</li></ul></div><div class="custom-block info"><div class="custom-block-title">评测配置</div><p><strong>Base 评测</strong></p><ul><li>通用：MMLU/MMLU-Pro <code>5-shot</code>，BBH <code>3-shot</code>。</li><li>代码：EvalPlus、MultiPL-E <code>0-shot</code>，MBPP <code>3-shot</code>；数学 MATH <code>4-shot CoT</code>。</li></ul><p><strong>Instruct 评测</strong></p><ul><li>快、慢思考分别评估数学、代码、逻辑、指令遵循和 Agent，不混成同一模式成绩。</li><li>Agent：BFCL v3、τ-Bench、ComplexFuncBench、C3-Bench。</li><li>长文本：PenguinScrolls、LongBench-v2、FRAMES；RULER QA 按长度分组至 <code>128K</code>。</li></ul><p><strong>吞吐测试</strong></p><ul><li>精度 <code>W16A16/KV16</code>，输入 <code>2048</code>，对比不同 Batch 与输出长度。</li></ul></div><h3 id="关键结果-hunyuan-a13b-base-与-sft-rl" tabindex="-1">关键结果(Hunyuan-A13B，Base 与 SFT/RL) <a class="header-anchor" href="#关键结果-hunyuan-a13b-base-与-sft-rl" aria-label="Permalink to &quot;关键结果(Hunyuan-A13B，Base 与 SFT/RL)&quot;">​</a></h3><p><strong>🍑 关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">Base 与后训练表现</div><p><strong>低激活 Base</strong></p><ul><li>与 Hunyuan-Large 对比，<code>13B</code> 激活替代 <code>52B</code>，<code>12/14</code> 项评测更好。</li><li>MMLU-Pro <code>60.20 → 67.23</code>，MBPP <code>72.60 → 83.86</code>，说明较低激活量仍能改善知识和代码能力。</li></ul><p><strong>慢思考 Instruct</strong></p><ul><li>AIME 2024 <code>87.3</code>，Qwen3-A22B <code>85.7</code>；AIME 2025 <code>76.8</code>，低于对照的 <code>81.5</code>。</li><li>LiveCodeBench <code>63.9</code>，低于 Qwen3-A22B <code>70.7</code>；复杂代码仍有提升空间。</li><li>BFCL v3 <code>78.3</code>，高于 Qwen3-A22B <code>70.8</code>；工具调用是本模型较突出的方向。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">快慢思考与长上下文</div><p><strong>快思考 → 慢思考</strong></p><ul><li>AIME 2024：<code>30.6 → 87.3</code>；LiveCodeBench：<code>27.4 → 63.9</code>，复杂推理明显受益。</li><li>BFCL v3：<code>65.9 → 78.3</code>；但 ComplexFuncBench：<code>74.0 → 61.2</code>。</li><li>因而慢思考不保证所有工具任务更好，模式选择应结合任务与实际质量。</li></ul><p><strong>长文本能力</strong></p><ul><li>LongBench-v2 <code>55.0</code>，高于 Qwen3-A22B <code>48.4</code>；FRAMES <code>81.1</code>，低于对照 <code>84.0</code>。</li><li>RULER QA 的 <code>64K～128K</code> 组为 <code>73.9</code>，优于报告中 R1 <code>65.6</code> 与 Qwen3-A22B <code>66.6</code>。</li><li>长输入利用较稳定，但跨来源检索与推理仍弱于部分对照，扩窗口不等于解决多跳 RAG。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">后续改进方向</div><p><strong>报告中的不足</strong></p><ul><li><strong>代码推理</strong>：LiveCodeBench 等复杂编程任务与更强模型仍有差距。</li><li><strong>多跳 RAG</strong>：继续改进检索结果整合与事实推理，提高 FRAMES 类任务表现。</li></ul><p><strong>笔记归纳</strong></p><ul><li>按任务比较快慢模式的质量与耗时，训练更准确的推理深度选择，减少无收益的长 CoT。</li></ul></div><h2 id="_2411-hunyuan-large-389b-a52b、cla、recycle-routing" tabindex="-1">(2411) Hunyuan-Large (389B-A52B、CLA、Recycle Routing) <a class="header-anchor" href="#_2411-hunyuan-large-389b-a52b、cla、recycle-routing" aria-label="Permalink to &quot;(2411) Hunyuan-Large (389B-A52B、CLA、Recycle Routing)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Hunyuan-Large 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2411.02265" target="_blank" rel="noreferrer">paper</a>，<a href="https://github.com/Tencent/Tencent-Hunyuan-Large" target="_blank" rel="noreferrer">代码与模型</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>大规模 MoE 需要同时处理长文 KV Cache、专家负载不均和高质量训练数据不足。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>架构与专家优化</strong>：<code>389B-A52B</code> MoE，GQA/CLA 共享 KV；Recycle Routing 将过载 token 重分配到空闲专家。</li><li><strong>数据与预训练</strong>：<code>7T tokens</code>，含约 <code>1.5T</code> 合成数据；结合 MoE Scaling Law、专家独立学习率与长上下文训练。</li><li><strong>SFT 与偏好优化</strong>：<code>1M+</code> 数据 SFT → 离线/在线混合 DPO，加入 Chosen SFT Loss 与 EMA。</li></ul><p><strong>模型效果(Hunyuan-Large-Instruct，SFT+DPO)</strong></p><ul><li>MMLU <code>89.9</code>、MATH <code>77.4</code>、HumanEval <code>90.0</code>；Llama3.1-405B-Instruct 分别为 <code>87.3、73.8、89.0</code>。</li><li>PenguinScrolls <code>85.23</code>，对照 Llama3.1-70B-Instruct <code>69.37</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>低激活 MoE 可以取得较强通用能力，但 GPQA 等专业推理仍弱于部分更大模型。</li><li>长文效果需要按长度评估：短上下文不一定领先，<code>64K～128K</code> 的稳定性更突出。</li></ul><p><strong>核心贡献</strong></p><ul><li>给出合成数据、KV 共享、专家路由和偏好训练结合的大规模 MoE 方案，开放 Base/Instruct 权重。</li></ul><p><strong>未来方向</strong></p><ul><li>用更贴近真实文档与多轮场景的评测推进长上下文能力，并继续优化 MoE 训练效率。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">MoE 规模化的训练与推理难点</div><p><strong>长文缓存与路由负载</strong></p><ul><li>KV Cache 随长度和层数增长，限制长上下文推理的显存与并发。</li><li>热门专家超过容量后会丢弃 token；单纯增加容量又降低计算效率。</li></ul><p><strong>数据与优化差异</strong></p><ul><li>自然语料中的数学、代码和低资源领域覆盖不足，需要可验证的高质量补充。</li><li>共享专家处理所有 token，路由专家只处理一部分，同一全局 Batch 对应不同有效 Batch。</li></ul></div><h3 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="架构与专家优化" tabindex="-1">架构与专家优化 <a class="header-anchor" href="#架构与专家优化" aria-label="Permalink to &quot;架构与专家优化&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">两个维度共享 KV</div><p><strong>Head 共享</strong></p><ul><li><code>80个 Query Head</code> 共用 <code>8组 KV Head</code>，先通过 GQA 减少 KV 副本。</li></ul><p><strong>跨层共享</strong></p><ul><li>CLA 让相邻 <code>2层</code>共享 KV Cache，在 Head 共享基础上进一步减半。</li><li>该配置的 KV 规模约为普通 MHA 的 <code>(8/80) × (1/2)=5%</code>。</li><li>Query 仍按层计算；共享的是用于读取历史的 KV，目标是减少长文缓存开销。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">专家分工与溢出处理</div><p><strong>混合路由</strong></p><ul><li><code>1个共享专家</code>处理所有 token，学习共通知识。</li><li><code>16个路由专家</code>按 token 分配，每次激活分数最高的 <code>1个</code>。</li></ul><p><strong>Recycle Routing</strong></p><ul><li>专家达到容量上限后，把原本会被丢弃的 token 分配到其他未满专家。</li><li>例：Expert 1 已满，原路由到它的 token D 改交有余量的 Expert 4。</li><li>保留这些 token 的训练信号，同时避免所有专家按最大负载分配计算资源。</li></ul></div><div class="custom-block info"><div class="custom-block-title">按有效 Batch 调整学习率</div><p><strong>有效 Batch 不同</strong></p><ul><li>共享专家每步接收全部 <code>B</code> 个 token；负载均衡时，单个路由专家约接收 <code>B/16</code>。</li><li>因此共享专家与路由专家的梯度统计不同，不应只根据全局 Batch 设置统一学习率。</li></ul><p><strong>优化策略</strong></p><ul><li>使用 AdamW，根据有效 Batch 与梯度噪声规模估计适合的学习率。</li><li>对共享专家和路由专家分别设置学习率尺度，改善训练效率与稳定性。</li></ul></div><h4 id="数据与预训练" tabindex="-1">数据与预训练 <a class="header-anchor" href="#数据与预训练" aria-label="Permalink to &quot;数据与预训练&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">1.5T 合成语料</div><p><strong>指令生成与演化</strong></p><ul><li>从网页、问答、代码和书籍提取知识丰富的种子，组合不同 Prompt 生成指令。</li><li>改善指令清晰度，扩充低资源领域，并逐步增加题目难度。</li></ul><p><strong>答案生成与筛选</strong></p><ul><li>多个领域专长模型生成答案，补充数学、代码和高教育价值内容。</li><li>Critique Model 检查质量，客观题用多答案自一致性排除不可靠样本。</li><li>合成语料约 <code>1.5T tokens</code>，与自然文本一起进入 <code>7T</code> 预训练。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">语料处理与 Tokenizer</div><p><strong>语料质量</strong></p><ul><li>按写作质量、教育价值和有害内容筛选，以中文、英文为主。</li><li>分类标签用于控制不同数据类型的比例，并处理隐私信息。</li></ul><p><strong>Tokenizer</strong></p><ul><li><code>128K</code> 词表：<code>100K</code> tiktoken 词条 + <code>28K</code> 中文词条。</li><li>增加中文压缩效率，减少同一文本需要的 token 数量。</li></ul></div><div class="custom-block info"><div class="custom-block-title">激活参数与训练数据分配</div><p><strong>小规模探索</strong></p><ul><li>用不同激活参数规模和训练数据量构造 IsoFLOP 对照，拟合固定算力下的模型/数据分配。</li><li>计算预算纳入 MoE 激活量、Attention 开销与 Batch 效率，避免直接套 Dense 的总参数公式。</li><li>在较平坦的最优区域选择 <code>52B</code> 激活与 <code>7T tokens</code>，兼顾训练效果和实际资源。</li></ul><p><strong>训练日程</strong></p><ul><li>预热 → 长阶段缓慢衰减 → 最后 <code>5% tokens</code> 快速退火。</li><li>退火阶段使用更高质量语料，学习率降到峰值的 <code>1/10</code>。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">两阶段长度扩展</div><p><strong>数据混合</strong></p><ul><li>以书籍和代码等自然长文本为主，长文本约 <code>25%</code>、普通长度数据约 <code>75%</code>。</li><li>保留短文本训练，扩展长度时兼顾原有通用能力。</li></ul><p><strong>训练设置</strong></p><ul><li>依次训练 <code>32K</code> 和 <code>256K</code>，每阶段约 <code>10B tokens</code>。</li><li><code>256K</code> 阶段将 RoPE Base 调整到 <code>1e9</code>。</li></ul></div><h4 id="sft-与偏好优化" tabindex="-1">SFT 与偏好优化 <a class="header-anchor" href="#sft-与偏好优化" aria-label="Permalink to &quot;SFT 与偏好优化&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">指令数据 Pipeline</div><p><strong>提取与扩展</strong></p><ul><li>领域模型从公开资料提取指令和参考答案，覆盖数学、逻辑、知识问答等。</li><li>训练指令泛化模型，将简单指令扩成更复杂任务，定向补充薄弱类别。</li><li>对候选数据做多维标签与类型平衡，减少近义重复和领域失衡。</li></ul><p><strong>质量筛选</strong></p><ul><li>从 <code>10M+</code> 候选中筛选 <code>1M+</code> 条 SFT 数据。</li><li>规则处理截断、乱码、重复和格式问题。</li><li>基于 Hunyuan <code>70B Dense</code> 的 Critique Model 按准确、相关、完整、有用、清晰评分。</li><li>最后加入人工复核，保证任务回答符合预期。</li></ul></div><div class="custom-block important"><div class="custom-block-title">DPO 对齐</div><p><strong>偏好数据</strong></p><ul><li>离线部分使用预先整理的偏好对，提供稳定的行为约束。</li><li>在线部分由当前 Policy 同题生成多个答案，Reward Model 选出最优与最差回答。</li><li>两类数据在同一阶段训练，使偏好样本既覆盖原有要求，也反映当前模型的错误。</li></ul><p><strong>稳定训练</strong></p><ul><li>DPO 外加入 Chosen 回答的 SFT Loss，避免好回答的概率随训练一起下降。</li><li>使用 EMA 平滑更新，减轻 Reward Hacking 与通用能力损失。</li><li>报告将该阶段置于 RLHF 小节，具体优化算法是 DPO。</li></ul></div><h3 id="实验设置-hunyuan-large-预训练-sft-dpo" tabindex="-1">实验设置(Hunyuan-Large，预训练 + SFT/DPO) <a class="header-anchor" href="#实验设置-hunyuan-large-预训练-sft-dpo" aria-label="Permalink to &quot;实验设置(Hunyuan-Large，预训练 + SFT/DPO)&quot;">​</a></h3><p><strong>✍️ 实验设置</strong></p><div class="custom-block tip"><div class="custom-block-title">模型与训练</div><p><strong>基础模型</strong></p><ul><li><code>389B-A52B</code>，<code>64层</code>，<code>hidden=6400</code>；共享专家 <code>1</code>，路由专家 <code>16/Top-1</code>。</li><li>GQA <code>80 Query / 8 KV</code>；CLA 每 <code>2层</code>共享 KV，RoPE + SwiGLU。</li></ul><p><strong>数据与超参</strong></p><ul><li>预训练 <code>7T tokens</code>，合成数据约 <code>1.5T</code>；优化器 AdamW。</li><li>长上下文训练 <code>32K → 256K</code>，各 <code>10B tokens</code>，长/短文本约 <code>1:3</code>。</li><li>SFT <code>1M+</code> 条、<code>3 epochs</code>，<code>lr=2e-5→2e-6</code>。</li><li>SFT 正则：<code>attention_dropout=0.1, hidden_dropout=0.2</code>；随后进行离线/在线混合 DPO。</li></ul><p><strong>Scaling Law 实验</strong></p><ul><li>MoE 激活参数从 <code>10M</code> 到 <code>1B</code>，训练数据从 <code>10B</code> 到 <code>100B tokens</code>。</li><li>用不同预算下的 IsoFLOP 曲线估计适合的激活参数与数据量。</li></ul></div><div class="custom-block info"><div class="custom-block-title">评测任务与设置</div><p><strong>Base / Instruct</strong></p><ul><li>Base：MMLU 等 <code>5-shot</code>、BBH/MBPP <code>3-shot</code>、MATH/GSM8K <code>4-shot</code>、HumanEval <code>0-shot</code>。</li><li>Instruct：通用知识、数学、代码，及 AlignBench、MT-Bench、IFEval、Arena-Hard、AlpacaEval。</li><li>对照包含 Llama3.1、Mixtral、DeepSeek，同类 Base 与 Instruct 分开比较。</li></ul><p><strong>长上下文</strong></p><ul><li>RULER、LV-Eval 按长度分段，覆盖到 <code>128K</code>；LV-Eval 使用 LLM Judge。</li><li>PenguinScrolls 使用真实长文、多轮、中英文任务，包含提取、定位、定性分析和数值推理。</li></ul></div><h3 id="关键结果-hunyuan-large-instruct-sft-dpo" tabindex="-1">关键结果(Hunyuan-Large-Instruct + SFT/DPO) <a class="header-anchor" href="#关键结果-hunyuan-large-instruct-sft-dpo" aria-label="Permalink to &quot;关键结果(Hunyuan-Large-Instruct + SFT/DPO)&quot;">​</a></h3><p><strong>🍑 关键结果</strong></p><div class="custom-block important"><div class="custom-block-title">通用能力与后训练</div><p><strong>Base 能力</strong></p><ul><li>MMLU <code>88.4</code>，对照 Llama3.1-405B <code>85.2</code>；MATH <code>69.8</code>，对照 <code>53.8</code>。</li><li>说明 <code>52B</code> 激活的 MoE 配合高质量数据，可以取得较强基础能力。</li></ul><p><strong>Instruct 效果</strong></p><ul><li>MMLU <code>89.9</code>、MATH <code>77.4</code>、HumanEval <code>90.0</code>，均高于报告中的 Llama3.1-405B-Instruct。</li><li>Arena-Hard <code>81.8</code>、AlpacaEval-2.0 <code>51.8</code>，开放式指令与偏好任务表现较强。</li><li>GPQA-Diamond <code>42.4</code>，低于 Llama3.1-405B-Instruct <code>51.1</code>，高难科学推理仍是短板。</li></ul><p><strong>训练经验</strong></p><ul><li>报告发现适当 Dropout 对 MoE SFT 更有帮助，强调大容量稀疏模型同样需要控制过拟合。</li><li>Chosen SFT Loss 直接保留好回答的学习信号，补充仅拉开偏好差距的 DPO 目标。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">长文稳定性与实际任务</div><p><strong>长度变化</strong></p><ul><li>RULER 的 <code>64K～128K</code> 组：Hunyuan <code>89.53</code>，Llama3.1-70B-Instruct <code>86.48</code>。</li><li>在更短区间，对照模型略高；Hunyuan 的优势主要体现为超长输入下退化较小。</li><li>LV-Eval 的 <code>64K～128K</code> 组：<code>67.87</code> 对 <code>61.57</code>，含干扰信息的长文问答也改善。</li></ul><p><strong>真实文档</strong></p><ul><li>PenguinScrolls 总分 <code>85.23</code>，对照 <code>69.37</code>；信息定位、定性分析和数值推理均改善。</li><li>数值推理为 <code>67.46</code>，低于自身信息提取 <code>91.14</code>，说明读到信息之后的计算仍更困难。</li></ul></div><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block info"><div class="custom-block-title">长上下文与 MoE 后续研究</div><p><strong>报告方向</strong></p><ul><li>开放模型与 PenguinScrolls，借助真实文档、多轮和多语言评测继续优化长文本能力。</li><li>将 MoE Scaling Law 与训练经验用于后续模型的规模和数据预算分配。</li></ul><p><strong>笔记归纳</strong></p><ul><li>重点补充科学推理与长文数值推理数据，避免把信息检索能力等同于复杂推理能力。</li></ul></div>',66)]))}const h=l(t,[["render",d]]);export{p as __pageData,h as default};
